"""Build the offline click-reaction study without changing desktop behavior."""
from pathlib import Path
root=Path(__file__).resolve().parents[1]
out=root/'dist/previews/Clawd-Click-Reactions-Lab.html'
css='''*{box-sizing:border-box}html{color-scheme:light}body{margin:0;background:#f5f2eb;color:#514638;font:14px/1.6 system-ui,"Microsoft YaHei",sans-serif;padding:20px 12px}main{max-width:780px;margin:auto;background:#faf7f0;border:1px solid #ded5c5;border-radius:18px;overflow:hidden}header{padding:22px 24px 0}h1{font-size:21px;margin:0 0 5px}p{margin:0;font-size:13px;color:#8a7a66}.scene{padding:6px 12px 0;touch-action:none;user-select:none;position:relative}.station{transform:translate(0,0);transform-origin:center}.scene svg{display:block;width:100%;max-height:470px}.scene #body-motion,.scene #left-hand,.scene #right-hand{cursor:grab}.scene:active #body-motion{cursor:grabbing}.controls{padding:0 24px 22px}.choices{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}button{border:1px solid #d8cfc1;background:#f0e9dc;border-radius:8px;padding:8px 12px;color:inherit;font:inherit;cursor:pointer}button[aria-pressed="true"]{background:#d97757;color:#fff;border-color:#d97757}button:focus-visible{outline:2px solid #d995aa;outline-offset:2px}textarea{display:block;width:100%;min-height:65px;resize:vertical;border:1px solid #d8cfc1;border-radius:9px;padding:10px 12px;background:#fffdf8;color:#514638;font:15px/1.6 system-ui;margin-top:8px}.key.is-down .key-top,.is-clicked{fill:#f2bf72}.hint{font-size:12px;color:#8a7a66}.status-row{display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;border-top:1px solid #e4dccf;padding-top:10px}[data-status]{color:#b46c50}[data-context-menu]{position:fixed;z-index:10;min-width:176px;background:#fffaf1;border:1px solid #d8cfc1;border-radius:10px;padding:5px;box-shadow:0 5px 16px #4a3a2520}[data-context-menu] button{display:block;border:0;background:transparent;width:100%;text-align:left}[data-context-menu] button:hover{background:#f0e9dc}[hidden]{display:none!important}@media(max-width:480px){body{padding:9px}header{padding:16px 16px 0}.controls{padding:0 16px 18px}.scene{padding:4px 0 0}.choices button{padding:8px 10px}}'''
svg=(root/'web/clawd-scene.svg').read_text(encoding='utf-8')
rig=(root/'web/rig-data.json').read_text(encoding='utf-8')
scripts=[(root/p).read_text(encoding='utf-8') for p in ['web/core/clawd.bundle.js','web/core/clawd-reach.js','web/core/clawd-reactions.js','web/click-reactions-preview.js']]
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Clawd · 戳戳互动实验台</title><style>'''+css+'''</style></head><body><main id="click-preview"><header><h1>戳戳小蟹，它会怎么回应？</h1><p>轻点身体看回应；按住移动拖动工位；右击打开菜单。</p></header><div class="scene" data-mouse-zone><div class="station">'''+svg+'''</div></div><div class="controls"><div class="status-row"><span data-gesture-status>等你轻轻戳一下</span><span data-status></span></div><div class="choices"><button type="button" data-reaction-choice="random" aria-pressed="true">随机回应</button><button type="button" data-reaction-choice="curious" aria-pressed="false">歪头挠挠 ？</button><button type="button" data-reaction-choice="shy" aria-pressed="false">害羞爱心 ♡</button><button type="button" data-reaction-choice="jelly" aria-pressed="false">Duang！</button><button type="button" data-reaction-choice="sing" aria-pressed="false">摇摇唱歌 ♪</button><button type="button" data-home>工位归位</button></div><p class="hint">选择一种反应可立即预览，之后轻点身体会重复这一种。唱歌先用动作和音符表现。</p><textarea spellcheck="false" placeholder="也可以打字：互动会先完整播完，再继续啪嗒。"></textarea><span class="hint" data-last-key>小短手已经就位</span></div></main><div data-context-menu hidden><button type="button" data-menu-random>改为随机回应</button><button type="button" data-menu-home>工位归位</button></div><script type="application/json" id="clawd-rig-data">'''+rig+'''</script>'''+''.join('<script>'+s+'</script>' for s in scripts)+'''</body></html>'''
out.parent.mkdir(exist_ok=True,parents=True);out.write_text(html,encoding='utf-8',newline='\n')
print(out)
